-- R&M group charge-code catalog.
--
-- Owner ruling 2026-10-25: OneFortyOne's charge-code numbers become the R&M
-- group standard (R&M, Mainland Pest Control, and the work R&M does for its
-- clients). A charge code is Source (C1, 1 digit) + Subject (C2, 2 digits) +
-- Issue (C3, 2 digits); OneFortyOne's 269-row list is reproduced exactly
-- (origin "onefortyone", with its Contract/Extra basis). Labels OneFortyOne
-- does not number get the next free numbers by the same logic (subjects from
-- 27, issues from 76; origin "derived", billing basis unassigned until the
-- owner prices them). Every Source/Subject/Issue combination observed across
-- the ACTIVE patrol workbooks, the MPC log, and the OFO pest invoices is
-- catalogued; misspelt or plural workbook labels are aliases, never new codes.
--
-- Pest-control charge codes carry the client GL crosswalk evidenced by the MPC
-- log ("Summary 2026": new 36xx/37xx codes beside the old 8558 accounts). No
-- species-specific GL exists in any source, so species other than goat keep
-- the "Animal: Other" GL and the charge code itself is the species index.
--
-- The catalog is seeded on the two classifying operators (R&M and Mainland).
-- Client organisations see the code and labels on their own records; the
-- catalog is not copied into every client.
--
-- Also: "Removal" means removing a covert camera or CCTV device (DART's
-- Equipment|Uninstall is a trap uninstall, not a removal); gate and sign
-- installation/removal/maintenance/manufacture is engineering work while a
-- gate recorded open/live or closed/dead is patrol reporting; ammunition is a
-- material used; equipment type is recorded separately. Mainland's ownership
-- by R&M is recorded as a non-access fact (canon ORG_SERVICE_MODEL, Model A:
-- every organisation is own-rooted; tree parentage would widen access).
--
-- Catalog and rule data only. No location_events row is reclassified here.

ALTER TABLE public.reference_codes DROP CONSTRAINT IF EXISTS reference_codes_code_type_check;
ALTER TABLE public.reference_codes ADD CONSTRAINT reference_codes_code_type_check CHECK (
  code_type = ANY (ARRAY[
    'pay_item'::text, 'gl_account'::text, 'role_code'::text, 'job_code'::text,
    'branch'::text, 'org_code'::text, 'service_code'::text,
    'work_subject'::text, 'work_activity'::text, 'biosecurity_species'::text,
    'equipment_type'::text, 'material_type'::text,
    'charge_code'::text, 'charge_source'::text, 'charge_subject'::text, 'charge_issue'::text
  ])
);

ALTER TABLE public.reference_code_templates DROP CONSTRAINT IF EXISTS reference_code_templates_type_check;
ALTER TABLE public.reference_code_templates ADD CONSTRAINT reference_code_templates_type_check CHECK (
  code_type = ANY (ARRAY[
    'work_subject'::text, 'work_activity'::text, 'biosecurity_species'::text,
    'equipment_type'::text, 'material_type'::text
  ])
);

CREATE OR REPLACE FUNCTION public.enforce_import_value_rule_catalog_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_code public.reference_codes%rowtype;
BEGIN
  SELECT * INTO v_code FROM public.reference_codes WHERE id = NEW.target_code_id;
  IF NOT FOUND OR v_code.organization_id <> NEW.organization_id
     OR v_code.code_type NOT IN ('work_subject', 'work_activity', 'biosecurity_species', 'equipment_type', 'material_type') THEN
    RAISE EXCEPTION 'Classification rule target must be an organization work subject, work activity, biosecurity species, equipment type, or material type code';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.enforce_import_value_rule_catalog_scope() FROM PUBLIC, anon, authenticated, service_role;

