INSERT INTO public.reference_codes(
  organization_id, code_type, code, name, description, is_active, sort_order, external_refs
)
SELECT organization.id,
       seed.row->>'code_type',
       seed.row->>'code',
       seed.row->>'name',
       CASE
         WHEN seed.row->'external_refs'->>'origin' = 'onefortyone' AND seed.row->>'code_type' = 'charge_code'
           THEN 'OneFortyOne charge code; billing basis ' || coalesce(seed.row->'external_refs'->>'billing_basis', 'not stated') || '.'
         WHEN seed.row->'external_refs'->>'origin' = 'onefortyone'
           THEN 'OneFortyOne charge-code component.'
         WHEN seed.row->>'code_type' = 'charge_code'
           THEN 'R&M group code derived from the OneFortyOne component numbering; billing basis not yet assigned.'
         ELSE 'R&M group charge-code component numbered after the OneFortyOne list.'
       END,
       true,
       (seed.row->>'sort_order')::integer,
       seed.row->'external_refs'
FROM seed
CROSS JOIN operators
JOIN public.organizations organization ON organization.id = operators.organization_id
ON CONFLICT (organization_id, code_type, code) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  is_active = true,
  sort_order = EXCLUDED.sort_order,
  external_refs = EXCLUDED.external_refs,
  updated_at = now();

