       'OneFortyOne general-ledger account used on R&M group charges.', true, gl_seed.sort_order, gl_seed.external_refs
FROM gl_seed
JOIN public.organizations organization ON organization.id = 'c48c1aaf-236b-417c-bbce-938c151662d6'::uuid
ON CONFLICT (organization_id, code_type, code) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  is_active = true,
  sort_order = EXCLUDED.sort_order,
  external_refs = EXCLUDED.external_refs,
  updated_at = now();

-- Mainland Pest Control is an R&M subsidiary. Corporate ownership is recorded
-- as a fact; it grants no access (parent_organization_id stays NULL).
UPDATE public.organizations
SET external_refs = external_refs || jsonb_build_object('corporate_group', jsonb_build_object(
      'parent_organization_id', 'e96d71c9-28a6-4d4a-b0f3-1c4ecdaa9c13',
      'relationship', 'subsidiary',
      'grants_access', false,
      'recorded_from', 'owner ruling 2026-10-25',
      'canon', 'docs/canon/ORG_SERVICE_MODEL.md Model A: organisations are own-rooted; access comes from service agreements')),
    updated_at = now()
WHERE id = '1ccdd3fb-0b0a-478d-8441-6f14a85172aa'::uuid
  AND NOT (external_refs ? 'corporate_group');

-- R&M label rules. Lower priority wins.
WITH rule_seed(rule_code, target_type, target_code, priority, conditions) AS (
  VALUES
    ('subject_pest_device', 'work_subject', 'pest_device', 15, '[{"field":"subject","operator":"in","values":["Equipment","Equipments","Equipmnt"]},{"field":"source","operator":"exact","value":"PEST CONTROL"}]'::jsonb),
    ('subject_animal', 'work_subject', 'animal', 15, '[{"field":"subject","operator":"in","values":["Animal Cull","Animal Seen","Animal Shot","Animal Patrol","Animal via camera","Animal","Animals","Animals culled","Animals seen","Animals shot","Animal patrols","Culling"]}]'::jsonb),
    ('subject_electronic_lock_issue', 'work_subject', 'electronic_lock', 5, '[{"field":"subject","operator":"regex","value":"^(locks?|e-locks?)$"},{"field":"issue","operator":"regex","value":"^e-?locks?\\b"}]'::jsonb),
